module.exports=[206402,a=>{"use strict";var b=a.i(388282);let c=[{title:"General Dentistry Course",slug:"general-dentistry-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course1`,discount:"10",startingPrice:"49,000",price:"54,444",duration:"45 days",handsOn:!1,description:"Learn the fundamentals of clinical dentistry including diagnosis, treatment planning, restorative procedures, and patient management."},{title:"Basic Implant Course",slug:"basic-implant-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course6`,discount:"10",startingPrice:"60,000",handsOn:!1,price:"66667",duration:"4 months",description:"An introductory implantology course covering implant planning, placement protocols, instruments, and restorative basics."},{title:"Endodontic Course",slug:"endodontic-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course2`,discount:"10",startingPrice:"15,000",price:"16,667",duration:"3 days",handsOn:!1,description:"Master root canal procedures, rotary endodontics, access preparation, obturation techniques, and endodontic case management."},{title:"Prosthodontics Course",slug:"prosthodontics-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course3`,discount:"10",startingPrice:"20,000",price:"22,222",duration:"3 days",handsOn:!1,description:"Gain hands-on experience in crowns, bridges, dentures, smile rehabilitation, and fixed prosthodontic procedures."},{title:"Oral Surgery Course",slug:"oral-surgery-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course4`,discount:"10",startingPrice:"30,000",price:"33,333",duration:"15 days",handsOn:!1,description:"Understand surgical extractions, flap design, suturing techniques, impaction management, and minor oral surgical procedures."},{title:"Complete Implant Course",slug:"complete-implant-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course6`,discount:"10",startingPrice:"99,000",handsOn:!1,price:"1,10,000",duration:"3 months",description:"Comprehensive implant training with advanced surgical protocols, sinus lift concepts, prosthetic workflows, and live cases."},{title:"Radiology (CBCT) Course",slug:"radiology-cbct-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course7`,discount:"10",startingPrice:"15,000",price:"16,667",duration:"2 days",handsOn:!0,description:"Learn CBCT interpretation, radiographic diagnosis, imaging protocols, and digital treatment planning for modern dentistry."},{title:"Esthetic Dentistry",slug:"esthetic-dentistry-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course8`,discount:"10",startingPrice:"49,000",price:"54,444",duration:"3 days",handsOn:!0,description:"Explore smile designing, veneers, teeth whitening, composite artistry, and minimally invasive cosmetic dental procedures."},{title:"Orthodontic Course",slug:"orthodontic-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course9`,discount:"10",startingPrice:"99,000",price:"1,10,000",duration:"6 months",handsOn:!1,description:"Study orthodontic diagnosis, treatment planning, wire bending basics, aligners, and fixed appliance mechanics."},{title:"Laser Course",slug:"laser-dentistry-course",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course10`,discount:"10",startingPrice:"15,000",price:"16,667",duration:"2 days",handsOn:!0,description:"Get trained in dental laser applications for soft tissue procedures, periodontal therapy, pain management, and esthetics."}],d=[{question:"Who can enroll in this course?",answer:"The course is designed for dental students, interns, and practicing dentists looking to enhance their clinical skills."},{question:"Will I receive a certificate after completion?",answer:"Yes, participants receive a certificate of completion upon successfully finishing the course."}],e={tag:"WHAT YOU WILL GAIN",points:["Hands-on clinical exposure","Real patient case discussions","Expert mentorship","Certificate of completion","Practical treatment planning skills","Enhanced clinical confidence"]},f=[{slug:"general-dentistry-course",hero:{title:"General Dentistry Course",subtitle:"Build a strong foundation in modern clinical dentistry.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course1`},overview:{tag:"OVERVIEW",description:"This comprehensive course covers the essential principles of diagnosis, treatment planning, restorative procedures, preventive dentistry, and patient management. Participants gain practical insights into day-to-day clinical dentistry and develop confidence in managing routine dental cases."},details:[{title:"Comprehensive Oral Examination and Diagnosis",description:"Learn how to perform a systematic oral examination and identify common dental conditions through clinical evaluation and radiographic interpretation. The course covers diagnostic protocols, case history recording, risk assessment, and methods to arrive at accurate treatment decisions for routine dental cases."},{title:"Treatment Planning and Restorative Procedures",description:"Understand the principles of treatment planning and sequencing of dental procedures for optimal patient outcomes. Participants will learn cavity preparation techniques, restorative material selection, direct restorations, and evidence-based approaches for managing common restorative cases in daily practice."},{title:"Preventive Dentistry and Patient Management",description:"Develop expertise in preventive care strategies including oral hygiene education, fluoride therapy, scaling recommendations, and long-term maintenance planning. The course also focuses on patient communication, informed consent, treatment acceptance, and building trust for successful clinical practice."}],curriculum:{tag:"CURRICULUM",points:["Comprehensive Oral Examination","Diagnosis & Treatment Planning","Restorative Procedures","Preventive Dentistry","Patient Communication","Clinical Case Discussions"]},benefits:e,faqs:d,courses:[{name:"General Dentistry - Short Course",duration:"45 Days",price:"49000"},{name:"General Dentistry - Long Course",duration:"3 to 6 Months",price:"99000"}]},{slug:"endodontic-course",courses:[{name:"Endodontics - Basic Course",duration:"3 Days",price:"15000"},{name:"Endodontics - Short Course",duration:"15 Days",price:"30000"},{name:"Endodontics - Long Course",duration:"2 Months",price:"49000"}],hero:{title:"Endodontic Course",subtitle:"Master modern root canal treatment techniques.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course2`},overview:{tag:"OVERVIEW",description:"Designed for dentists seeking expertise in endodontics, this course focuses on diagnosis, access cavity preparation, rotary instrumentation, obturation techniques, and management of complex root canal cases."},details:[{title:"Diagnosis and Treatment Planning in Endodontics",description:"Learn to diagnose pulpal and periapical pathologies through clinical examination, vitality testing, radiographic interpretation, and case assessment. The course covers differential diagnosis, case selection, treatment planning, and decision-making protocols for successful endodontic therapy."},{title:"Access Opening, Working Length and Canal Preparation",description:"Master the fundamental steps of root canal treatment including access cavity preparation, canal identification, working length determination, glide path creation, and biomechanical preparation. Participants will gain practical knowledge of hand files, rotary instrumentation systems, and irrigation protocols used in modern endodontics."},{title:"Obturation Techniques and Management of Complex Cases",description:"Understand the principles of three-dimensional obturation and post-endodontic restoration to achieve long-term treatment success. The course also covers the management of curved canals, calcified canals, retreatment cases, procedural errors, and methods to prevent common endodontic complications."}],curriculum:{tag:"CURRICULUM",points:["Endodontic Diagnosis","Access Preparation","Rotary Endodontics","Working Length Determination","Obturation Techniques","Management of Difficult Cases"]},benefits:e,faqs:d},{slug:"prosthodontics-course",courses:[{name:"Prosthodontics - Veneers, Inlay & Onlay",duration:"3 Days",price:"20000"},{name:"Prosthodontics - Comprehensive Course",duration:"15 Days",price:"30000"}],hero:{title:"Prosthodontics Course",subtitle:"Restore function, aesthetics, and confidence.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course3`},overview:{tag:"OVERVIEW",description:"Gain practical experience in crowns, bridges, dentures, fixed prosthodontics, and smile rehabilitation. Learn modern restorative workflows and treatment planning strategies."},details:[{title:"Principles of Prosthodontic Diagnosis and Treatment Planning",description:"Learn the fundamentals of prosthodontic diagnosis, patient evaluation, occlusal assessment, and treatment planning for partially and completely edentulous patients. The course focuses on selecting appropriate prosthetic solutions based on functional, aesthetic, and biological considerations."},{title:"Fixed and Removable Prosthodontic Procedures",description:"Gain in-depth knowledge of tooth preparation principles, impression techniques, temporization, and cementation procedures for crowns and bridges. Participants will also learn the design, fabrication, and clinical management of removable partial dentures and complete dentures."},{title:"Occlusion, Aesthetics, and Full Mouth Rehabilitation",description:"Understand the role of occlusion in prosthodontic success and learn techniques for achieving functional and aesthetic rehabilitation. The course covers smile design principles, vertical dimension assessment, occlusal rehabilitation, and multidisciplinary approaches for complex restorative cases."}],curriculum:{tag:"CURRICULUM",points:["Crown Preparation","Bridge Design","Complete Dentures","Partial Dentures","Smile Rehabilitation","Occlusion Principles"]},benefits:e,faqs:d},{slug:"oral-surgery-course",courses:[{name:"Oral Surgery",duration:"15 Days",price:"30000"}],hero:{title:"Oral Surgery Course",subtitle:"Develop confidence in surgical dental procedures.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course4`},overview:{tag:"OVERVIEW",description:"This course introduces participants to oral surgical procedures including extractions, flap design, suturing techniques, impaction management, and post-operative care."},details:[{title:"Patient Evaluation and Surgical Treatment Planning",description:"Learn the principles of case selection, medical history evaluation, clinical examination, and radiographic interpretation for oral surgical procedures. The course covers diagnosis, treatment planning, informed consent, and pre-operative assessment to ensure safe and predictable surgical outcomes."},{title:"Exodontia and Minor Oral Surgical Procedures",description:"Gain hands-on knowledge of extraction techniques including forceps and elevator principles, flap design, bone removal, tooth sectioning, and suturing methods. Participants will learn the management of routine extractions, impacted teeth, retained roots, and other minor oral surgical procedures."},{title:"Management of Surgical Complications and Post-Operative Care",description:"Understand the prevention and management of common surgical complications such as bleeding, dry socket, root fractures, oro-antral communication, and infection. The course also covers post-operative instructions, pain management, wound healing, and follow-up protocols for successful patient recovery."}],curriculum:{tag:"CURRICULUM",points:["Surgical Extractions","Flap Design","Suturing Techniques","Impaction Management","Post-operative Care","Minor Oral Surgery"]},benefits:e,faqs:d},{slug:"basic-implant-course",courses:[{name:"Basic Implant Course",duration:"3 to 4 Months",price:"60000"}],hero:{title:"Basic Implant Course",subtitle:"Start your journey into implant dentistry.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course6`},overview:{tag:"OVERVIEW",description:"An introductory implantology course covering treatment planning, implant placement concepts, instrumentation, and restorative basics for beginners."},details:[{title:"Case Selection and Implant Treatment Planning",description:"Learn the fundamentals of implant case selection, patient evaluation, CBCT interpretation, bone assessment, and treatment planning. The course covers indications and contraindications for implant therapy, implant positioning principles, and methods for selecting the appropriate implant system for different clinical situations."},{title:"Surgical Protocol for Implant Placement",description:"Gain practical knowledge of implant surgery including flap design, osteotomy preparation, implant insertion protocols, torque values, and achieving primary stability. Participants will understand the step-by-step workflow involved in single implant placement and immediate post-operative management."},{title:"Healing, Prosthetic Considerations, and Complication Management",description:"Understand the biological principles of osseointegration, healing timelines, and prosthetic planning for implant-supported restorations. The course also covers the prevention and management of common surgical complications, post-operative care, and long-term maintenance protocols for successful implant outcomes."}],curriculum:{tag:"CURRICULUM",points:["Implant Basics","Case Selection","Treatment Planning","Surgical Protocols","Implant Instruments","Restorative Concepts"]},benefits:e,faqs:d},{slug:"complete-implant-course",courses:[{name:"Complete Implant Course",duration:"3 to 6 Months",price:"99000"}],hero:{title:"Complete Implant Course",subtitle:"Comprehensive implantology from planning to restoration.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course6`},overview:{tag:"OVERVIEW",description:"An advanced implant training program featuring surgical placement, prosthetic workflows, bone augmentation concepts, and live clinical cases."},details:[{title:"Advanced Implant Diagnosis and Comprehensive Treatment Planning",description:"Develop expertise in advanced implant treatment planning through CBCT interpretation, bone quality assessment, prosthetically driven implant placement, and management of partially and completely edentulous patients. The course covers single tooth replacements, multiple implants, full arch rehabilitation, and interdisciplinary treatment planning for complex cases."},{title:"Advanced Surgical Techniques and Immediate Implant Protocols",description:"Master advanced implant surgical procedures including immediate implant placement, immediate loading protocols, guided implant surgery, flapless implant placement, sinus lift procedures, ridge expansion, and bone grafting techniques. Participants will gain a thorough understanding of surgical decision-making and case selection for predictable outcomes."},{title:"Implant Prosthetics, Complications, and Full Mouth Rehabilitation",description:"Learn the principles of implant prosthetics including impression techniques, abutment selection, screw-retained and cement-retained restorations, and occlusal considerations for implant-supported prostheses. The course also covers the management of surgical and prosthetic complications, peri-implant diseases, maintenance protocols, and full mouth implant rehabilitation workflows."}],curriculum:{tag:"CURRICULUM",points:["Advanced Implant Planning","Surgical Placement","Bone Augmentation Concepts","Immediate Loading","Prosthetic Workflows","Live Cases"]},benefits:e,faqs:d},{slug:"radiology-cbct-course",courses:[{name:"Radiology Course",duration:"2 Days",price:"15000"}],hero:{title:"Radiology (CBCT) Course",subtitle:"Master dental imaging and radiographic diagnosis.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course7`},overview:{tag:"OVERVIEW",description:"Learn CBCT interpretation, digital imaging workflows, radiographic diagnosis, and treatment planning using modern radiology techniques."},details:[{title:"Fundamentals of Dental Radiology and CBCT Imaging",description:"Learn the principles of dental radiology including image formation, radiation physics, exposure parameters, and radiation safety protocols. The course introduces the indications, advantages, and limitations of Cone Beam Computed Tomography (CBCT) and its role in modern dental diagnosis and treatment planning."},{title:"CBCT Interpretation and Anatomical Landmark Identification",description:"Develop the skills required to systematically interpret CBCT scans by identifying normal anatomical structures and pathological findings in the maxillofacial region. Participants will learn to evaluate bone quality, sinus anatomy, mandibular canal location, impacted teeth, periapical lesions, and other clinically relevant findings."},{title:"Clinical Applications of CBCT in Dentistry",description:"Understand the use of CBCT imaging in implant planning, endodontics, oral surgery, orthodontics, and TMJ assessment. The course covers three-dimensional treatment planning, measurement techniques, diagnostic workflows, and methods for integrating CBCT findings into everyday clinical practice for improved treatment outcomes."}],curriculum:{tag:"CURRICULUM",points:["CBCT Interpretation","Radiographic Anatomy","Diagnostic Imaging","Pathology Identification","Implant Planning","Digital Workflow Integration"]},benefits:e,faqs:d},{slug:"esthetic-dentistry-course",course:[{name:"Aesthetic Dentistry Course",duration:"3 Days",price:"49000"}],hero:{title:"Esthetic Dentistry Course",subtitle:"Create beautiful smiles with modern cosmetic dentistry.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course8`},overview:{tag:"OVERVIEW",description:"Explore smile design principles, veneers, whitening procedures, composite artistry, and minimally invasive cosmetic treatments."},details:[{title:"Principles of Smile Design and Facial Aesthetics",description:"Learn the fundamentals of aesthetic analysis including facial proportions, smile line evaluation, gingival architecture, tooth proportions, and dentofacial harmony. The course covers Digital Smile Design (DSD) concepts and methods for creating treatment plans that balance function with aesthetics."},{title:"Direct and Indirect Aesthetic Restorations",description:"Gain practical knowledge of modern aesthetic procedures including composite bonding, diastema closure, tooth reshaping, veneers, and ceramic restorations. Participants will learn material selection, shade matching protocols, layering techniques, and preparation principles for predictable aesthetic outcomes."},{title:"Minimally Invasive Cosmetic Dentistry Techniques",description:"Understand contemporary minimally invasive approaches to aesthetic dentistry including enamel preservation, adhesive dentistry, tooth whitening protocols, and conservative smile enhancement procedures. The course also covers case selection, patient communication, and long-term maintenance of aesthetic restorations."}],curriculum:{tag:"CURRICULUM",points:["Smile Design","Composite Bonding","Teeth Whitening","Veneers","Facial Aesthetics","Case Planning"]},benefits:e,faqs:d},{slug:"orthodontic-course",courses:[{name:"Orthodontics Course",duration:"3 to 6 Months",price:"99000"}],hero:{title:"Orthodontic Course",subtitle:"Learn the fundamentals of tooth movement and alignment.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course9`},overview:{tag:"OVERVIEW",description:"This course covers orthodontic diagnosis, treatment planning, aligners, fixed appliance therapy, and essential biomechanics."},details:[{title:"Orthodontic Diagnosis and Treatment Planning",description:"Learn the fundamentals of orthodontic diagnosis through facial analysis, cephalometric evaluation, space analysis, and occlusal assessment. The course covers classification of malocclusions, growth assessment, case selection, and treatment planning for both adolescent and adult patients."},{title:"Biomechanics and Appliance Therapy",description:"Develop a thorough understanding of orthodontic biomechanics including force systems, anchorage control, and tooth movement principles. Participants will learn the indications, mechanics, and clinical applications of fixed appliances, removable appliances, self-ligating brackets, and clear aligner therapy."},{title:"Management of Orthodontic Cases and Retention Protocols",description:"Understand the clinical management of crowding, spacing, crossbites, deep bites, open bites, and Class II and Class III malocclusions. The course also covers treatment progress monitoring, finishing and detailing, retention strategies, and prevention of relapse to achieve stable long-term outcomes."}],curriculum:{tag:"CURRICULUM",points:["Orthodontic Diagnosis","Treatment Planning","Aligners","Wire Bending","Fixed Appliances","Biomechanics"]},benefits:e,faqs:d},{slug:"laser-dentistry-course",courses:[{name:"Laser Course",duration:"2 Days",price:"15000"}],hero:{title:"Laser Dentistry Course",subtitle:"Discover the future of minimally invasive dental care.",image:`${b.CLOUDINARY_BASE}/rekha-dental/courses/course10`},details:[{title:"Fundamentals of Laser Physics and Tissue Interaction",description:"Learn the principles of laser technology, wavelength characteristics, and the interaction of laser energy with soft and hard oral tissues. The course covers different dental laser systems, tissue absorption properties, laser safety protocols, and selection criteria for various clinical applications."},{title:"Soft Tissue Applications in Laser Dentistry",description:"Develop expertise in soft tissue laser procedures including gingivectomy, frenectomy, operculectomy, depigmentation, crown lengthening, and management of soft tissue lesions. Participants will understand laser settings, technique selection, and methods to achieve precise tissue management with minimal discomfort and bleeding."},{title:"Hard Tissue Applications and Advanced Clinical Procedures",description:"Understand the applications of lasers in cavity preparation, caries removal, periodontal therapy, peri-implantitis management, and endodontic procedures. The course also covers post-operative care, complication management, and the integration of laser technology into modern dental practice for minimally invasive treatment outcomes."}],overview:{tag:"OVERVIEW",description:"Gain expertise in dental laser applications for soft tissue procedures, periodontal therapy, pain management, and aesthetic treatments."},curriculum:{tag:"CURRICULUM",points:["Laser Physics","Soft Tissue Applications","Periodontal Therapy","Pain Management","Aesthetic Procedures","Clinical Protocols"]},benefits:e,faqs:d}];b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE,b.CLOUDINARY_BASE;let g=[{id:1,title:"Live Implant Demonstration",subtitle:"Hands-on implant placement training conducted under expert supervision.",image:`${b.CLOUDINARY_BASE}/rekha-dental/extra/extra1`},{id:2,title:"Advanced Endodontic Workshop",subtitle:"Practical training focused on modern root canal treatment techniques.",image:`${b.CLOUDINARY_BASE}/rekha-dental/extra/extra2`},{id:3,title:"Clinical Case Discussion",subtitle:"Interactive learning sessions covering complex restorative cases and treatment planning.",image:`${b.CLOUDINARY_BASE}/rekha-dental/extra/extra3`}];a.s(["academyActivities",0,g,"academyCourses",0,c,"academyFaqData",0,[{question:"Who is eligible to enroll?",answer:"Our programs are designed for dental students, fresh graduates, practicing dentists, and clinicians looking to upgrade their clinical expertise."},{question:"How long are the courses?",answer:"Course durations vary depending on the program. Short-term workshops may last a few days, while advanced clinical programs can extend over several weeks."},{question:"What are the fees?",answer:"Fees differ based on the course structure, clinical exposure, and specialization. Detailed fee information is shared during the consultation and enrollment process."},{question:"What certification do I receive?",answer:"Participants receive an academy certification upon successful completion of the course, recognizing their practical and theoretical training."},{question:"Is accommodation provided?",answer:"Yes, we assist outstation and international participants with accommodation recommendations and nearby stay arrangements for a comfortable learning experience."},{question:"Will I work on real patients?",answer:"Selected advanced programs include supervised live patient exposure, allowing participants to gain real clinical experience under expert mentorship."}],"alumniReviewsData",0,[{review:"The hands-on implant sessions completely changed my confidence in clinical practice. The mentorship was exceptional throughout.",author:"Dr. Aarav Mehta",subtitle:"Complete Implant Course",rating:5},{review:"Unlike conventional workshops, this academy focused heavily on live patient exposure and real-world decision making.",author:"Dr. Raman Saxena",subtitle:"Endodontic Course",rating:5},{review:"The faculty were approachable, detail-oriented, and deeply invested in every participant’s growth.",author:"Dr. Rohan Kapoor",subtitle:"Esthetic Dentistry",rating:5},{review:"The CBCT training helped me integrate advanced radiology into my clinic immediately after the program.",author:"Dr. Karan Singh",subtitle:"Radiology (CBCT) Course",rating:5},{review:"Every session balanced theory with practical execution beautifully. It felt more like mentorship than a course.",author:"Dr. Ishaan Verma",subtitle:"Basic Implant Course",rating:5},{review:"The orthodontic module was incredibly structured and clinically relevant. I left with techniques I now use daily.",author:"Dr. Raj Singh",subtitle:"Orthodontic Course",rating:5}],"courseDetails",0,f])}];

